sp_widget.client_script:
api.controller = function($scope, $timeout, $window) {

    var c = this;


    /* =========================================================
       STATE
       ========================================================= */

    c.view = 'list';                 /* 'list' or 'evaluate' */

    c.interviews = [];
    c.pendingList = [];
    c.filteredPending = [];
    c.recent = [];
    c.distribution = [];

    c.stats = {
        total: 0, pending: 0, evaluated: 0,
        passed: 0, failed: 0, hold: 0
    };

    c.progress = 0;
    c.search = '';
    c.loading = false;

    c.selected = null;
    c.submitting = false;
    c.formError = '';
    c.successMessage = '';

    c.scale = [1, 2, 3, 4, 5];

    c.criteria = [
        { key: 'technical',       label: 'Technical Skills',  hint: 'Knowledge of the subject and role' },
        { key: 'communication',   label: 'Communication',     hint: 'Clarity, confidence and listening' },
        { key: 'problem_solving', label: 'Problem Solving',   hint: 'Logical and analytical thinking' },
        { key: 'professionalism', label: 'Professionalism',   hint: 'Attitude, punctuality and behaviour' }
    ];

    c.options = [
        { value: 'strong_hire', label: 'Strong Hire', icon: 'fa-star',         hint: 'Outstanding candidate' },
        { value: 'hire',        label: 'Hire',        icon: 'fa-thumbs-up',    hint: 'Meets the requirements' },
        { value: 'hold',        label: 'Hold',        icon: 'fa-pause-circle', hint: 'Needs another look' },
        { value: 'reject',      label: 'Reject',      icon: 'fa-thumbs-down',  hint: 'Not suitable' }
    ];

    c.form = emptyForm();


    /* =========================================================
       INITIALIZE
       ========================================================= */

    applyData();


    /* =========================================================
       DATA
       ========================================================= */

    function emptyForm() {
        return {
            technical: 0,
            communication: 0,
            problem_solving: 0,
            professionalism: 0,
            comments: '',
            recommendation: ''
        };
    }

    function applyData() {

        var d = c.data || {};

        c.interviews = angular.isArray(d.interviews) ? d.interviews : [];
        c.recent = angular.isArray(d.recent) ? d.recent : [];

        c.stats = d.stats || {
            total: 0, pending: 0, evaluated: 0,
            passed: 0, failed: 0, hold: 0
        };

        c.pendingList = c.interviews.filter(function(item) {
            return item.pending;
        });

        applySearch();

        var total = c.stats.total || 0;

        c.progress = total ?
            Math.round((c.stats.evaluated / total) * 100) :
            0;

        function percent(count) {
            return total ?
                Math.round(((count || 0) / total) * 100) :
                0;
        }

        c.distribution = [
            {
                label: 'Passed',
                count: c.stats.passed,
                percent: percent(c.stats.passed),
                cls: 'nxe-bar-pass'
            },
            {
                label: 'Failed',
                count: c.stats.failed,
                percent: percent(c.stats.failed),
                cls: 'nxe-bar-fail'
            },
            {
                label: 'On Hold',
                count: c.stats.hold,
                percent: percent(c.stats.hold),
                cls: 'nxe-bar-hold'
            },
            {
                label: 'Pending',
                count: c.stats.pending,
                percent: percent(c.stats.pending),
                cls: 'nxe-bar-pending'
            }
        ];
    }


    /* =========================================================
       SEARCH PENDING EVALUATIONS
       ========================================================= */

    function applySearch() {

        var query = String(c.search || '')
            .toLowerCase()
            .trim();

        if (!query) {
            c.filteredPending = c.pendingList.slice();
            return;
        }

        var words = query.split(/\s+/);

        c.filteredPending = c.pendingList.filter(function(item) {

            var text = [
                item.name,
                item.registerNumber,
                item.branch,
                item.company,
                item.position,
                item.interviewer
            ].join(' ').toLowerCase();

            return words.every(function(word) {
                return text.indexOf(word) !== -1;
            });
        });
    }

    c.applySearch = applySearch;

    c.clearSearch = function() {
        c.search = '';
        applySearch();
    };


    /* =========================================================
       REFRESH
       ========================================================= */

    c.refresh = function() {

        if (c.loading) {
            return;
        }

        c.loading = true;

        c.server.get({
            action: 'load'
        }).then(

            function(response) {

                c.loading = false;

                if (response && response.data) {
                    c.data = response.data;
                    applyData();
                }
            },

            function() {
                c.loading = false;
            }
        );
    };


    /* =========================================================
       OPEN / CLOSE EVALUATION
       ========================================================= */

    c.startEvaluation = function(interview) {

        /*
         * Placement Officer can see all interview records,
         * but cannot open the evaluation screen.
         *
         * Placement Admin and Interviewer can evaluate.
         */
        if (!c.data.canEvaluate) {
            return;
        }

        if (!interview) {
            return;
        }

        c.selected = interview;
        c.form = emptyForm();
        c.formError = '';
        c.successMessage = '';
        c.view = 'evaluate';

        scrollToTop();
    };

    c.cancelEvaluation = function() {

        if (c.submitting) {
            return;
        }

        c.view = 'list';
        c.selected = null;
        c.formError = '';

        scrollToTop();
    };

    function scrollToTop() {

        $timeout(function() {
            $window.scrollTo(0, 0);
        }, 50);
    }


    /* =========================================================
       RATINGS
       ========================================================= */

    c.setRating = function(key, value) {

        if (c.submitting) {
            return;
        }

        c.form[key] = value;
    };

    c.overallRating = function() {

        var f = c.form;

        if (
            !f.technical ||
            !f.communication ||
            !f.problem_solving ||
            !f.professionalism
        ) {
            return '—';
        }

        return (
            (
                f.technical +
                f.communication +
                f.problem_solving +
                f.professionalism
            ) / 4
        ).toFixed(1);
    };


    /* =========================================================
       SUBMIT
       ========================================================= */

    c.submitEvaluation = function() {

        if (c.submitting || !c.selected) {
            return;
        }

        c.formError = '';

        var f = c.form;

        if (
            !f.technical ||
            !f.communication ||
            !f.problem_solving ||
            !f.professionalism
        ) {
            c.formError = 'Please rate all four criteria.';
            return;
        }

        if (!f.comments || !f.comments.trim()) {
            c.formError = 'Please add your comments.';
            return;
        }

        if (!f.recommendation) {
            c.formError = 'Please select a recommendation.';
            return;
        }

        c.submitting = true;

        c.server.get({
            action: 'submit_evaluation',
            interview_id: c.selected.sys_id,
            technical: f.technical,
            communication: f.communication,
            problem_solving: f.problem_solving,
            professionalism: f.professionalism,
            comments: f.comments.trim(),
            recommendation: f.recommendation
        }).then(

            function(response) {

                c.submitting = false;

                var d = response && response.data;

                if (!d) {
                    c.formError = 'No response received from server.';
                    return;
                }

                if (d.submitError) {
                    c.formError = d.submitError;
                    return;
                }

                if (d.submitSuccess) {

                    /* server returned the refreshed lists */
                    c.data = d;
                    applyData();

                    c.view = 'list';
                    c.selected = null;
                    c.successMessage =
                        'Evaluation submitted successfully.';

                    scrollToTop();

                    $timeout(function() {
                        c.successMessage = '';
                    }, 5000);

                    return;
                }

                c.formError =
                    'Unable to submit the evaluation.';
            },

            function(error) {

                c.submitting = false;

                console.error(
                    'NEXORA EVALUATION ERROR:',
                    error
                );

                c.formError =
                    'Unable to submit the evaluation.';
            }
        );
    };


    /* =========================================================
       CSS HELPERS
       ========================================================= */

    c.outcomeClass = function(outcome) {

        if (outcome === 'pass') {
            return 'nxe-pill-pass';
        }

        if (outcome === 'fail') {
            return 'nxe-pill-fail';
        }

        if (outcome === 'hold') {
            return 'nxe-pill-hold';
        }

        return 'nxe-pill-pending';
    };

    c.statusClass = function(status) {

        var value = String(status || '')
            .toLowerCase()
            .replace(/_/g, ' ')
            .trim();

        if (value === 'completed') {
            return 'nxe-pill-pass';
        }

        if (value === 'scheduled') {
            return 'nxe-pill-blue';
        }

        if (value === 'in progress') {
            return 'nxe-pill-hold';
        }

        return 'nxe-pill-pending';
    };

};

sp_widget.css:
/* ============================================================
   NEXORA INTERVIEW EVALUATION  -  COMPLETE WIDGET CSS (v2)
   Layout: full-width pending panel, then Summary + Distribution
   side by side, then Recent Evaluations full width.
   Requires Font Awesome 4 (already used by ServiceNow portal).
============================================================ */

.nxe-page {
    --nxe-navy: #14233a;
    --nxe-text: #3b4a60;
    --nxe-muted: #8a97a8;
    --nxe-border: #e8edf3;
    --nxe-bg: #f4f6fa;
    --nxe-coral: #f47c68;
    --nxe-coral-dark: #e4634d;
    --nxe-coral-soft: #fff0ec;

    width: 85vw !important;
    
    min-height: 100vh !important;
    margin: 0 auto !important;
    padding: 70px !important;
    background: #ffffff !important;
    color: var(--nxe-text) !important;
    font-family: "Segoe UI", Arial, sans-serif !important;
    box-sizing: border-box !important;
}

.nxe-page *,
.nxe-page *:before,
.nxe-page *:after { box-sizing: border-box !important; }

.nxe-page button { font-family: inherit !important; }


/* ============================================================
   HERO
============================================================ */

.nxe-page .nxe-hero {
    position: relative !important;
    overflow: hidden !important;
    margin: 0 0 22px 0 !important;
    padding: 34px 38px !important;
    border-radius: 16px !important;
    background: linear-gradient(135deg, #14233a 0%, #1c3452 60%, #24466b 100%) !important;
    color: #fff !important;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 20px !important;
}

.nxe-page .nxe-hero:after {
    content: "" !important;
    position: absolute !important;
    right: -90px !important;
    top: -130px !important;
    width: 280px !important;
    height: 280px !important;
    border: 1px solid rgba(255,255,255,.12) !important;
    border-radius: 50% !important;
    pointer-events: none !important;
}

.nxe-page .nxe-hero-content { position: relative !important; z-index: 2 !important; }

.nxe-page .nxe-kicker {
    margin-bottom: 8px !important;
    color: var(--nxe-coral) !important;
    font-size: 11px !important;
    font-weight: 800 !important;
    letter-spacing: 2px !important;
}

.nxe-page .nxe-hero h1 {
    margin: 0 !important;
    padding: 0 !important;
    color: #fff !important;
    font-size: 32px !important;
    font-weight: 800 !important;
    line-height: 1.2 !important;
}

.nxe-page .nxe-hero p {
    margin: 8px 0 0 0 !important;
    color: #c9d6e4 !important;
    font-size: 13px !important;
}

.nxe-page .nxe-hero-icon {
    position: relative !important;
    z-index: 2 !important;
    width: 72px !important;
    height: 72px !important;
    min-width: 72px !important;
    border-radius: 18px !important;
    background: rgba(255,255,255,.1) !important;
    border: 1px solid rgba(255,255,255,.18) !important;
    color: var(--nxe-coral) !important;
    font-size: 30px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
}


/* ============================================================
   ALERTS
============================================================ */

.nxe-page .nxe-alert {
    margin: 0 0 18px 0 !important;
    padding: 13px 16px !important;
    border-radius: 10px !important;
    font-size: 13px !important;
    font-weight: 600 !important;
    display: flex !important;
    align-items: center !important;
    gap: 10px !important;
}

.nxe-page .nxe-alert-success { background: #e8f7ef !important; border: 1px solid #bfe6d1 !important; color: #17803f !important; }
.nxe-page .nxe-alert-error   { background: #fff0ee !important; border: 1px solid #f6c9c2 !important; color: #d4503f !important; }


/* ============================================================
   STAT CARDS
============================================================ */

.nxe-page .nxe-stat-grid {
    display: grid !important;
    grid-template-columns: repeat(4, 1fr) !important;
    gap: 16px !important;
    margin: 0 0 20px 0 !important;
}

.nxe-page .nxe-stat-card {
    padding: 20px !important;
    background: #fff !important;
    border: 1px solid var(--nxe-border) !important;
    border-radius: 14px !important;
    box-shadow: 0 2px 10px rgba(20,35,58,.04) !important;
    display: flex !important;
    align-items: center !important;
    gap: 14px !important;
}

.nxe-page .nxe-stat-icon {
    width: 48px !important;
    height: 48px !important;
    min-width: 48px !important;
    border-radius: 12px !important;
    font-size: 19px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
}

.nxe-page .nxe-blue   { background: #eaf2ff !important; color: #3b7ddd !important; }
.nxe-page .nxe-orange { background: var(--nxe-coral-soft) !important; color: var(--nxe-coral) !important; }
.nxe-page .nxe-green  { background: #e8f7ef !important; color: #22a05a !important; }
.nxe-page .nxe-purple { background: #f1ecff !important; color: #7a5bd0 !important; }

.nxe-page .nxe-stat-number {
    color: var(--nxe-navy) !important;
    font-size: 26px !important;
    font-weight: 800 !important;
    line-height: 1 !important;
}

.nxe-page .nxe-stat-label {
    margin-top: 6px !important;
    color: var(--nxe-muted) !important;
    font-size: 12px !important;
}


/* ============================================================
   LIST VIEW LAYOUT
   panel on top, side cards below in 2 columns, recent full width
============================================================ */

.nxe-page .nxe-layout {
    display: flex !important;
    flex-direction: column !important;
    gap: 20px !important;
}

.nxe-page .nxe-side {
    display: grid !important;
    grid-template-columns: 1fr 1fr !important;
    gap: 20px !important;
    align-items: stretch !important;
}

.nxe-page .nxe-side > .nxe-card:nth-child(3) { grid-column: 1 / -1 !important; }


/* ============================================================
   PANEL (PENDING EVALUATIONS)
============================================================ */

.nxe-page .nxe-panel {
    width: 100% !important;
    min-width: 0 !important;
    background: #fff !important;
    border: 1px solid var(--nxe-border) !important;
    border-radius: 14px !important;
    box-shadow: 0 2px 10px rgba(20,35,58,.04) !important;
    overflow: hidden !important;
}

.nxe-page .nxe-panel-header {
    padding: 20px 24px !important;
    border-bottom: 1px solid var(--nxe-border) !important;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    flex-wrap: wrap !important;
    gap: 14px !important;
}

.nxe-page .nxe-panel-header h2 {
    margin: 0 !important;
    color: var(--nxe-navy) !important;
    font-size: 16px !important;
    font-weight: 800 !important;
}

.nxe-page .nxe-panel-header h2:before {
    content: "\f0f6" !important;
    font-family: FontAwesome !important;
    margin-right: 10px !important;
    color: var(--nxe-coral) !important;
    font-weight: normal !important;
}

.nxe-page .nxe-panel-header p {
    margin: 4px 0 0 0 !important;
    color: var(--nxe-muted) !important;
    font-size: 11px !important;
}

.nxe-page .nxe-panel-tools {
    display: flex !important;
    align-items: center !important;
    gap: 10px !important;
    flex-wrap: wrap !important;
}


/* ============================================================
   SEARCH + BUTTONS
============================================================ */

.nxe-page .nxe-search {
    width: 250px !important;
    height: 38px !important;
    background: #fff !important;
    border: 1px solid #dde4ec !important;
    border-radius: 9px !important;
    display: flex !important;
    align-items: center !important;
}

.nxe-page .nxe-search:focus-within {
    border-color: var(--nxe-coral) !important;
    box-shadow: 0 0 0 3px rgba(244,124,104,.14) !important;
}

.nxe-page .nxe-search > i { margin-left: 12px !important; color: #9aa7b6 !important; }

.nxe-page .nxe-search input {
    flex: 1 !important;
    min-width: 0 !important;
    width: 100% !important;
    height: 36px !important;
    padding: 0 10px !important;
    border: 0 !important;
    outline: none !important;
    box-shadow: none !important;
    background: transparent !important;
    color: var(--nxe-text) !important;
    font-size: 12px !important;
}

.nxe-page .nxe-search button {
    padding: 8px 12px !important;
    border: 0 !important;
    background: transparent !important;
    color: #9aa7b6 !important;
    cursor: pointer !important;
}

.nxe-page .nxe-btn-light {
    height: 38px !important;
    padding: 0 16px !important;
    background: #fff !important;
    border: 1px solid #dde4ec !important;
    border-radius: 9px !important;
    color: var(--nxe-navy) !important;
    font-size: 12px !important;
    font-weight: 700 !important;
    cursor: pointer !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 7px !important;
    transition: all .15s ease !important;
}

.nxe-page .nxe-btn-light:hover:not(:disabled) { background: #f4f6fa !important; border-color: #cdd6e0 !important; }

.nxe-page .nxe-btn-primary {
    height: 42px !important;
    padding: 0 22px !important;
    background: var(--nxe-coral) !important;
    border: 0 !important;
    border-radius: 9px !important;
    color: #fff !important;
    font-size: 13px !important;
    font-weight: 700 !important;
    cursor: pointer !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 8px !important;
    box-shadow: 0 4px 12px rgba(244,124,104,.3) !important;
    transition: background .15s ease !important;
}

.nxe-page .nxe-btn-primary:hover:not(:disabled) { background: var(--nxe-coral-dark) !important; }

.nxe-page .nxe-btn-small {
    height: 32px !important;
    padding: 0 13px !important;
    font-size: 11px !important;
    border-radius: 8px !important;
    white-space: nowrap !important;
    box-shadow: none !important;
}

.nxe-page .nxe-btn-light:disabled,
.nxe-page .nxe-btn-primary:disabled { opacity: .55 !important; cursor: not-allowed !important; }


/* ============================================================
   TABLE
============================================================ */

.nxe-page .nxe-table-wrapper { width: 100% !important; overflow-x: auto !important; }

.nxe-page .nxe-table {
    width: 100% !important;
    min-width: 820px !important;
    margin: 0 !important;
    border-collapse: collapse !important;
    background: #fff !important;
}

.nxe-page .nxe-table thead th {
    padding: 12px 24px !important;
    background: #f8fafc !important;
    border-bottom: 1px solid var(--nxe-border) !important;
    color: #7a8798 !important;
    font-size: 10px !important;
    font-weight: 800 !important;
    letter-spacing: .8px !important;
    text-align: left !important;
    white-space: nowrap !important;
}

.nxe-page .nxe-table tbody td {
    padding: 14px 24px !important;
    border-bottom: 1px solid #f0f3f7 !important;
    color: var(--nxe-text) !important;
    font-size: 12px !important;
    vertical-align: middle !important;
}

.nxe-page .nxe-table tbody tr:hover { background: #fafbfd !important; }


/* ============================================================
   PERSON / AVATAR
============================================================ */

.nxe-page .nxe-person { display: flex !important; align-items: center !important; gap: 12px !important; }

.nxe-page .nxe-avatar {
    width: 38px !important;
    height: 38px !important;
    min-width: 38px !important;
    border-radius: 50% !important;
    background: var(--nxe-coral-soft) !important;
    color: var(--nxe-coral-dark) !important;
    font-size: 14px !important;
    font-weight: 800 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
}

.nxe-page .nxe-avatar-small { width: 32px !important; height: 32px !important; min-width: 32px !important; font-size: 12px !important; }

.nxe-page .nxe-avatar-large {
    width: 60px !important;
    height: 60px !important;
    min-width: 60px !important;
    font-size: 22px !important;
    background: var(--nxe-navy) !important;
    color: #fff !important;
}

.nxe-page .nxe-person-info { display: flex !important; flex-direction: column !important; gap: 3px !important; min-width: 0 !important; }
.nxe-page .nxe-person-info strong { color: var(--nxe-navy) !important; font-size: 12px !important; font-weight: 700 !important; }
.nxe-page .nxe-person-info span   { color: var(--nxe-muted) !important; font-size: 11px !important; }


/* ============================================================
   PILLS
============================================================ */

.nxe-page .nxe-pill {
    display: inline-flex !important;
    align-items: center !important;
    padding: 5px 11px !important;
    border-radius: 20px !important;
    font-size: 10px !important;
    font-weight: 700 !important;
    white-space: nowrap !important;
    background: #eef1f5 !important;
    color: #5f6f82 !important;
}

.nxe-page .nxe-pill-pass    { background: #e8f7ef !important; color: #17803f !important; }
.nxe-page .nxe-pill-fail    { background: #ffeeeb !important; color: #d4503f !important; }
.nxe-page .nxe-pill-hold    { background: #fff6e0 !important; color: #b7791f !important; }
.nxe-page .nxe-pill-blue    { background: #eaf2ff !important; color: #3b7ddd !important; }
.nxe-page .nxe-pill-pending { background: #eef1f5 !important; color: #5f6f82 !important; }


/* ============================================================
   EMPTY STATE  (orange check icon, like the screenshot)
============================================================ */

.nxe-page .nxe-empty-row {
    padding: 44px 20px !important;
    text-align: center !important;
}

.nxe-page .nxe-empty-row i {
    display: block !important;
    margin-bottom: 10px !important;
    color: var(--nxe-coral) !important;
    font-size: 28px !important;
}

.nxe-page .nxe-empty-row strong { display: block !important; color: var(--nxe-navy) !important; font-size: 12px !important; font-weight: 700 !important; }
.nxe-page .nxe-empty-row span   { display: block !important; margin-top: 5px !important; color: var(--nxe-muted) !important; font-size: 11px !important; }


/* ============================================================
   CARDS  (header strip with icon + title, like the screenshot)
============================================================ */

.nxe-page .nxe-card {
    padding: 22px 24px 24px !important;
    background: #fff !important;
    border: 1px solid var(--nxe-border) !important;
    border-radius: 14px !important;
    box-shadow: 0 2px 10px rgba(20,35,58,.04) !important;
    overflow: hidden !important;
}

.nxe-page .nxe-card h3 {
    margin: -22px -24px 20px -24px !important;
    padding: 18px 24px !important;
    border-bottom: 1px solid var(--nxe-border) !important;
    color: var(--nxe-navy) !important;
    font-size: 15px !important;
    font-weight: 800 !important;
}

/* icons for the three side cards */
.nxe-page .nxe-side > .nxe-card h3:before {
    font-family: FontAwesome !important;
    margin-right: 10px !important;
    color: var(--nxe-coral) !important;
    font-weight: normal !important;
}
.nxe-page .nxe-side > .nxe-card:nth-child(1) h3:before { content: "\f080" !important; } /* bar-chart */
.nxe-page .nxe-side > .nxe-card:nth-child(2) h3:before { content: "\f200" !important; } /* pie-chart */
.nxe-page .nxe-side > .nxe-card:nth-child(3) h3:before { content: "\f1da" !important; } /* history   */


/* ============================================================
   EVALUATION SUMMARY
============================================================ */

.nxe-page .nxe-progress-head {
    margin-bottom: 8px !important;
    color: var(--nxe-muted) !important;
    font-size: 12px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
}

.nxe-page .nxe-progress-head strong { color: var(--nxe-navy) !important; font-size: 13px !important; }

.nxe-page .nxe-progress {
    width: 100% !important;
    height: 6px !important;
    border-radius: 6px !important;
    background: #eef1f6 !important;
    overflow: hidden !important;
}

.nxe-page .nxe-progress-fill {
    height: 100% !important;
    border-radius: 6px !important;
    background: var(--nxe-coral) !important;
    transition: width .4s ease !important;
}

.nxe-page .nxe-summary-list { list-style: none !important; margin: 16px 0 0 0 !important; padding: 0 !important; }

.nxe-page .nxe-summary-list li {
    padding: 10px 0 !important;
    border-top: 1px solid #f0f3f7 !important;
    color: var(--nxe-muted) !important;
    font-size: 12px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
}

.nxe-page .nxe-summary-list li strong { color: var(--nxe-navy) !important; font-weight: 800 !important; }


/* ============================================================
   RESULT DISTRIBUTION  (rows become tiles, like the screenshot)
============================================================ */

.nxe-page .nxe-side > .nxe-card:nth-child(2) {
    display: grid !important;
    grid-template-columns: repeat(4, 1fr) !important;
    gap: 12px !important;
    align-content: start !important;
}

.nxe-page .nxe-side > .nxe-card:nth-child(2) h3 { grid-column: 1 / -1 !important; margin-bottom: 8px !important; }

.nxe-page .nxe-dist-row {
    padding: 16px 8px 14px !important;
    background: #fff !important;
    border: 1px solid var(--nxe-border) !important;
    border-radius: 12px !important;
    text-align: center !important;
}

.nxe-page .nxe-dist-label {
    margin-bottom: 10px !important;
    display: flex !important;
    flex-direction: column-reverse !important;
    align-items: center !important;
    gap: 4px !important;
}

.nxe-page .nxe-dist-label span {
    color: var(--nxe-muted) !important;
    font-size: 10px !important;
    font-weight: 700 !important;
    letter-spacing: .5px !important;
    text-transform: uppercase !important;
}

.nxe-page .nxe-dist-label strong {
    color: var(--nxe-navy) !important;
    font-size: 22px !important;
    font-weight: 800 !important;
    line-height: 1 !important;
}

.nxe-page .nxe-bar { width: 100% !important; height: 4px !important; border-radius: 4px !important; background: #eef1f6 !important; overflow: hidden !important; }
.nxe-page .nxe-bar-fill { height: 100% !important; border-radius: 4px !important; transition: width .4s ease !important; }

.nxe-page .nxe-bar-pass    { background: #22a05a !important; }
.nxe-page .nxe-bar-fail    { background: #e5484d !important; }
.nxe-page .nxe-bar-hold    { background: #d9a21b !important; }
.nxe-page .nxe-bar-pending { background: #9fb0c3 !important; }


/* ============================================================
   RECENT EVALUATIONS
============================================================ */

.nxe-page .nxe-recent-empty {
    padding: 22px 0 8px !important;
    text-align: center !important;
    color: #9aa7b6 !important;
    font-size: 11px !important;
}

.nxe-page .nxe-recent-item {
    padding: 12px 0 !important;
    border-bottom: 1px solid #f0f3f7 !important;
    display: flex !important;
    align-items: center !important;
    gap: 12px !important;
}

.nxe-page .nxe-recent-item:last-child { border-bottom: 0 !important; padding-bottom: 0 !important; }
.nxe-page .nxe-recent-info { flex: 1 !important; }

.nxe-page .nxe-recent-info strong {
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
}


/* ============================================================
   EVALUATE VIEW
============================================================ */

.nxe-page .nxe-evaluate {
    width: 100% !important;
    max-width: 960px !important;
    margin: 0 auto !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 18px !important;
}

.nxe-page .nxe-back {
    align-self: flex-start !important;
    padding: 9px 15px !important;
    background: #fff !important;
    border: 1px solid #dde4ec !important;
    border-radius: 9px !important;
    color: var(--nxe-navy) !important;
    font-size: 12px !important;
    font-weight: 700 !important;
    cursor: pointer !important;
    display: inline-flex !important;
    align-items: center !important;
    gap: 8px !important;
}

.nxe-page .nxe-back:hover:not(:disabled) { background: var(--nxe-navy) !important; color: #fff !important; border-color: var(--nxe-navy) !important; }
.nxe-page .nxe-back:disabled { opacity: .5 !important; cursor: not-allowed !important; }

/* inside the evaluate view the card titles don't use the header strip icons */
.nxe-page .nxe-evaluate .nxe-card h3 { margin-bottom: 16px !important; }

.nxe-page .nxe-candidate-head {
    margin-bottom: 20px !important;
    padding-bottom: 20px !important;
    border-bottom: 1px solid var(--nxe-border) !important;
    display: flex !important;
    align-items: center !important;
    gap: 16px !important;
}

.nxe-page .nxe-candidate-head h2 { margin: 0 !important; color: var(--nxe-navy) !important; font-size: 22px !important; font-weight: 800 !important; }
.nxe-page .nxe-candidate-head p  { margin: 4px 0 0 0 !important; color: var(--nxe-muted) !important; font-size: 12px !important; }

.nxe-page .nxe-info-grid { display: grid !important; grid-template-columns: repeat(4, 1fr) !important; gap: 12px !important; }

.nxe-page .nxe-info {
    padding: 13px 15px !important;
    background: #f8fafc !important;
    border: 1px solid var(--nxe-border) !important;
    border-radius: 10px !important;
    min-width: 0 !important;
}

.nxe-page .nxe-info span {
    display: block !important;
    margin-bottom: 5px !important;
    color: var(--nxe-muted) !important;
    font-size: 10px !important;
    font-weight: 700 !important;
    letter-spacing: .5px !important;
    text-transform: uppercase !important;
}

.nxe-page .nxe-info strong { display: block !important; color: var(--nxe-navy) !important; font-size: 13px !important; word-break: break-word !important; }


/* ---------- RATINGS ---------- */

.nxe-page .nxe-rating-row {
    padding: 15px 0 !important;
    border-bottom: 1px solid #f0f3f7 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    flex-wrap: wrap !important;
    gap: 16px !important;
}

.nxe-page .nxe-rating-text strong { display: block !important; color: var(--nxe-navy) !important; font-size: 13px !important; }
.nxe-page .nxe-rating-text span   { display: block !important; margin-top: 3px !important; color: var(--nxe-muted) !important; font-size: 11px !important; }

.nxe-page .nxe-stars { display: flex !important; align-items: center !important; gap: 4px !important; }

.nxe-page .nxe-star {
    padding: 4px !important;
    border: 0 !important;
    background: transparent !important;
    color: #cdd6e0 !important;
    font-size: 22px !important;
    line-height: 1 !important;
    cursor: pointer !important;
    transition: transform .12s ease, color .12s ease !important;
}

.nxe-page .nxe-star:hover { transform: scale(1.18) !important; color: #f0a920 !important; }
.nxe-page .nxe-star-on { color: #f0a920 !important; }

.nxe-page .nxe-rating-value { min-width: 66px !important; margin-left: 10px !important; color: var(--nxe-muted) !important; font-size: 11px !important; font-weight: 700 !important; }

.nxe-page .nxe-overall {
    margin-top: 16px !important;
    padding: 14px 18px !important;
    border-radius: 10px !important;
    background: var(--nxe-coral-soft) !important;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
}

.nxe-page .nxe-overall span   { color: var(--nxe-coral-dark) !important; font-size: 12px !important; font-weight: 700 !important; }
.nxe-page .nxe-overall strong { color: var(--nxe-navy) !important; font-size: 24px !important; font-weight: 800 !important; }
.nxe-page .nxe-overall small  { color: var(--nxe-muted) !important; font-size: 12px !important; font-weight: 600 !important; }


/* ---------- COMMENTS ---------- */

.nxe-page .nxe-required { color: #e5484d !important; }

.nxe-page .nxe-textarea {
    width: 100% !important;
    min-height: 120px !important;
    padding: 13px 15px !important;
    background: #fff !important;
    border: 1px solid #dde4ec !important;
    border-radius: 10px !important;
    color: var(--nxe-text) !important;
    font-family: inherit !important;
    font-size: 13px !important;
    line-height: 1.6 !important;
    outline: none !important;
    box-shadow: none !important;
    resize: vertical !important;
}

.nxe-page .nxe-textarea:focus { border-color: var(--nxe-coral) !important; box-shadow: 0 0 0 3px rgba(244,124,104,.14) !important; }
.nxe-page .nxe-textarea:disabled { background: #f8fafc !important; cursor: not-allowed !important; }


/* ---------- RECOMMENDATION OPTIONS ---------- */

.nxe-page .nxe-options { display: grid !important; grid-template-columns: repeat(4, 1fr) !important; gap: 12px !important; }

.nxe-page .nxe-option {
    padding: 16px 12px !important;
    background: #fff !important;
    border: 2px solid var(--nxe-border) !important;
    border-radius: 12px !important;
    cursor: pointer !important;
    text-align: center !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    gap: 5px !important;
    transition: all .15s ease !important;
}

.nxe-page .nxe-option i { margin-bottom: 4px !important; font-size: 22px !important; }
.nxe-page .nxe-option strong { color: var(--nxe-navy) !important; font-size: 13px !important; }
.nxe-page .nxe-option span   { color: var(--nxe-muted) !important; font-size: 11px !important; }

.nxe-page .nxe-option:hover:not(:disabled) { transform: translateY(-2px) !important; box-shadow: 0 8px 18px rgba(20,35,58,.08) !important; }
.nxe-page .nxe-option:disabled { opacity: .6 !important; cursor: not-allowed !important; }

.nxe-page .nxe-option-strong_hire i { color: #7a5bd0 !important; }
.nxe-page .nxe-option-hire i        { color: #22a05a !important; }
.nxe-page .nxe-option-hold i        { color: #d9a21b !important; }
.nxe-page .nxe-option-reject i      { color: #e5484d !important; }

.nxe-page .nxe-option-active.nxe-option-strong_hire { border-color: #7a5bd0 !important; background: #f6f2ff !important; }
.nxe-page .nxe-option-active.nxe-option-hire        { border-color: #22a05a !important; background: #eefaf3 !important; }
.nxe-page .nxe-option-active.nxe-option-hold        { border-color: #d9a21b !important; background: #fffaeb !important; }
.nxe-page .nxe-option-active.nxe-option-reject      { border-color: #e5484d !important; background: #fff2f2 !important; }


/* ---------- ACTIONS ---------- */

.nxe-page .nxe-actions {
    padding-bottom: 16px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: flex-end !important;
    gap: 12px !important;
}

.nxe-page .nxe-actions .nxe-btn-light { height: 42px !important; padding: 0 22px !important; }


/* ============================================================
   UNAUTHORIZED (outside .nxe-page)
============================================================ */

.nxe-unauthorized {
    padding: 80px 20px !important;
    text-align: center !important;
    color: #7a8798 !important;
    font-family: "Segoe UI", Arial, sans-serif !important;
}

.nxe-unauthorized i  { color: #c4cdd8 !important; font-size: 40px !important; }
.nxe-unauthorized h2 { margin: 14px 0 8px !important; color: #14233a !important; }
.nxe-unauthorized p  { margin: 0 !important; font-size: 14px !important; }
.nxe-unauthorized .nxe-unauthorized-note { margin-top: 10px !important; color: #a2adb9 !important; font-size: 12px !important; }


/* ============================================================
   RESPONSIVE
============================================================ */

@media screen and (max-width: 1000px) {
    .nxe-page .nxe-side { grid-template-columns: 1fr !important; }
    .nxe-page .nxe-side > .nxe-card:nth-child(3) { grid-column: auto !important; }
    .nxe-page .nxe-stat-grid { grid-template-columns: repeat(2, 1fr) !important; }
    .nxe-page .nxe-info-grid,
    .nxe-page .nxe-options { grid-template-columns: repeat(2, 1fr) !important; }
}

@media screen and (max-width: 700px) {
    .nxe-page { padding: 14px !important; }
    .nxe-page .nxe-hero { padding: 24px !important; }
    .nxe-page .nxe-hero h1 { font-size: 26px !important; }
    .nxe-page .nxe-hero-icon { display: none !important; }
    .nxe-page .nxe-side > .nxe-card:nth-child(2) { grid-template-columns: repeat(2, 1fr) !important; }
    .nxe-page .nxe-panel-header { padding: 16px !important; }
    .nxe-page .nxe-panel-tools,
    .nxe-page .nxe-search { width: 100% !important; }
}

@media screen and (max-width: 520px) {
    .nxe-page .nxe-stat-grid,
    .nxe-page .nxe-info-grid,
    .nxe-page .nxe-options { grid-template-columns: 1fr !important; }
    .nxe-page .nxe-rating-row { flex-direction: column !important; align-items: flex-start !important; }
    .nxe-page .nxe-actions { flex-direction: column-reverse !important; }
    .nxe-page .nxe-actions button { width: 100% !important; }
}

sp_widget.script:
(function() {



    /* =========================================================
       CONFIGURATION
       ========================================================= */

    var INTERVIEW_TABLE   = 'x_snc_college_pl_0_interview';
    var APPLICATION_TABLE = 'x_snc_college_pl_0_application';
    var STUDENT_TABLE     = 'x_snc_college_pl_0_student';
    var DRIVE_TABLE       = 'x_snc_college_pl_0_placement_drive';


    var INTERVIEWER_FIELDS = ['interviewer', 'assigned_to', 'interviewer_user'];
    var DATE_FIELDS        = ['interview_date', 'date'];
    var TIME_FIELDS        = ['interview_time', 'time'];
    var RESULT_FIELDS      = ['result', 'interview_result'];
    var FEEDBACK_FIELDS    = ['feedback', 'interview_feedback'];
    var STATUS_FIELDS      = ['status', 'state'];



    /* =========================================================
       INITIAL DATA
       ========================================================= */

    data.authorized = false;
    data.role = '';
    data.message = '';

    data.interviews = [];
    data.recent = [];

    data.stats = {
        total: 0,
        pending: 0,
        evaluated: 0,
        passed: 0,
        failed: 0,
        hold: 0,
        cancelled: 0
    };

    data.submitSuccess = false;
    data.submitError = '';



    /* =========================================================
       ROLE CHECK
       ========================================================= */

    var isAdmin       = gs.hasRole('x_snc_college_pl_0.placement_admin');
    var isOfficer     = gs.hasRole('x_snc_college_pl_0.placement_officer');
    var isInterviewer = gs.hasRole('x_snc_college_pl_0.interviewer');


    if (!isAdmin && !isOfficer && !isInterviewer) {

        data.message = 'Your account needs the placement_admin, placement_officer or interviewer role.';
        return;

    }


    data.authorized = true;


    data.role = isAdmin ? 'Placement Admin' :
                (isOfficer ? 'Placement Officer' : 'Interviewer');

    /*
     * Placement Admin  -> Can evaluate
     * Placement Officer -> Cannot evaluate
     * Interviewer      -> Can evaluate
     */
    data.canEvaluate = isAdmin || isInterviewer;


    /* Admin and officer see every interview; an interviewer sees only his / her own */
    var seeAll = isAdmin || isOfficer;



    /* =========================================================
       CACHES (avoid reading the same record again and again)
       ========================================================= */

    var applicationCache = {};
    var studentCache = {};
    var driveCache = {};



    /* =========================================================
       MAIN
       ========================================================= */

    try {


        if (input && input.action === 'submit_evaluation') {

            submitEvaluation();

        }


        loadInterviews();


    } catch (error) {


        gs.error('NEXORA INTERVIEW EVALUATION ERROR: ' + error);
        data.message = 'Unable to load interview evaluations.';

    }



    /* =========================================================
       LOAD INTERVIEWS
       ========================================================= */

    function loadInterviews() {


        data.interviews = [];
        data.recent = [];


        data.stats = {
            total: 0,
            pending: 0,
            evaluated: 0,
            passed: 0,
            failed: 0,
            hold: 0,
            cancelled: 0
        };


        var gr = new GlideRecord(INTERVIEW_TABLE);


        if (!gr.isValid()) {

            data.message = 'Interview table was not found.';
            return;

        }


        /*
         * IMPORTANT:
         * Placement Admin and Placement Officer
         * can see ALL interview records.
         *
         * Interviewer sees only their own interviews.
         */
        if (!seeAll) {


            var interviewerField = findField(gr, INTERVIEWER_FIELDS);


            if (!interviewerField) {

                data.message = 'The interview table has no interviewer field.';
                return;

            }


            gr.addQuery(interviewerField, gs.getUserID());

        }


        var dateField = findField(gr, DATE_FIELDS);


        if (dateField) {

            gr.orderByDesc(dateField);

        } else {

            gr.orderByDesc('sys_created_on');

        }


        gr.query();


        var evaluatedItems = [];


        while (gr.next()) {


            var item = buildInterview(gr);


            /* cancelled interviews do not need an evaluation */
            if (item.cancelled) {

                data.stats.cancelled++;
                continue;

            }


            data.interviews.push(item);
            data.stats.total++;


            if (item.evaluated) {


                data.stats.evaluated++;


                if (item.outcome === 'pass') {

                    data.stats.passed++;

                } else if (item.outcome === 'fail') {

                    data.stats.failed++;

                } else {

                    data.stats.hold++;

                }


                evaluatedItems.push(item);


            } else {


                data.stats.pending++;

            }

        }



        /* Recent evaluations: the 5 most recently updated */
        evaluatedItems.sort(function(a, b) {

            if (a.updated < b.updated) {
                return 1;
            }

            if (a.updated > b.updated) {
                return -1;
            }

            return 0;

        });


        for (var i = 0; i < evaluatedItems.length && i < 5; i++) {


            data.recent.push({

                sys_id: evaluatedItems[i].sys_id,
                name: evaluatedItems[i].name,
                initial: evaluatedItems[i].initial,
                company: evaluatedItems[i].company,
                result: evaluatedItems[i].result,
                outcome: evaluatedItems[i].outcome,
                updated: evaluatedItems[i].updatedDisplay

            });

        }

    }



    /* =========================================================
       BUILD ONE INTERVIEW OBJECT
       ========================================================= */

    function buildInterview(gr) {


        var appId = '';
        var studentId = '';
        var driveId = '';


        if (gr.isValidField('application')) {

            appId = gr.getValue('application') || '';

        }


        if (gr.isValidField('student')) {

            studentId = gr.getValue('student') || '';

        }


        var app = appId ? getApplication(appId) : null;


        if (!studentId && app) {

            studentId = app.student;

        }


        var driveField = findField(gr, ['drive', 'placement_drive']);


        if (driveField) {

            driveId = gr.getValue(driveField) || '';

        }


        if (!driveId && app) {

            driveId = app.drive;

        }


        var student = studentId ? getStudent(studentId) : null;
        var drive = driveId ? getDrive(driveId) : null;



        /* Company / position */
        var company = '';


        if (gr.isValidField('company')) {

            company = gr.getDisplayValue('company') || '';

        }


        if (!company && drive) {

            company = drive.company;

        }


        var position = getFirstValidValue(
            gr,
            ['position', 'job_role', 'role', 'round_name']
        );


        if (!position && drive) {

            position = drive.position;

        }



        /* Date / time */
        var dateField = findField(gr, DATE_FIELDS);
        var timeField = findField(gr, TIME_FIELDS);


        var date = dateField ?
            (gr.getDisplayValue(dateField) || '') : '';

        var time = timeField ?
            (gr.getDisplayValue(timeField) || '') : '';


        if (!time && date.indexOf(' ') !== -1) {

            var parts = date.split(' ');

            date = parts[0];
            time = parts.slice(1).join(' ');

        }


        var status = getFirstValidValue(gr, STATUS_FIELDS);
        var result = getFirstValidValue(gr, RESULT_FIELDS);
        var outcome = classifyResult(result);


        var name = student ? student.name : 'Unknown Student';


        return {

            sys_id: gr.getUniqueValue(),

            name: name,
            initial: getInitial(name),
            registerNumber: student ? student.registerNumber : '',
            branch: student ? student.branch : '',
            year: student ? student.year : '',
            cgpa: student ? student.cgpa : '',
            backlogs: student ? student.backlogs : '',

            company: company,
            position: position,
            date: date,
            time: time,
            interviewer: getFirstValidValue(gr, INTERVIEWER_FIELDS),

            status: status,
            result: result,
            feedback: getFirstValidValue(gr, FEEDBACK_FIELDS),

            outcome: outcome,
            evaluated: outcome !== 'none',
            pending: outcome === 'none',
            cancelled: normalize(status).indexOf('cancel') !== -1,

            updated: gr.getValue('sys_updated_on') || '',
            updatedDisplay: gr.getDisplayValue('sys_updated_on') || ''

        };

    }



    /* =========================================================
       SUBMIT EVALUATION
       ========================================================= */

    function submitEvaluation() {


        data.submitSuccess = false;
        data.submitError = '';


        try {


            /*
             * IMPORTANT SECURITY CHECK
             *
             * Placement Officer can SEE records,
             * but cannot submit an evaluation.
             */
            if (!data.canEvaluate) {

                data.submitError =
                    'Placement Officers are not allowed to evaluate interviews.';

                return;

            }


            var interviewId =
                String(input.interview_id || '').trim();

            var recommendation =
                String(input.recommendation || '').trim();

            var comments =
                String(input.comments || '').trim();


            var technical =
                toRating(input.technical);

            var communication =
                toRating(input.communication);

            var problemSolving =
                toRating(input.problem_solving);

            var professionalism =
                toRating(input.professionalism);



            /* ---------- validation ---------- */


            if (!technical ||
                !communication ||
                !problemSolving ||
                !professionalism) {

                data.submitError =
                    'Please rate all four criteria.';

                return;

            }


            if (!comments) {

                data.submitError =
                    'Please add your comments.';

                return;

            }


            var recommendations = {

                strong_hire: {
                    label: 'Strong Hire',
                    outcome: 'pass'
                },

                hire: {
                    label: 'Hire',
                    outcome: 'pass'
                },

                hold: {
                    label: 'Hold',
                    outcome: 'hold'
                },

                reject: {
                    label: 'Reject',
                    outcome: 'fail'
                }

            };


            if (!recommendations[recommendation]) {

                data.submitError =
                    'Please select a recommendation.';

                return;

            }



            /* ---------- find the interview ---------- */


            var gr = new GlideRecord(INTERVIEW_TABLE);


            if (!interviewId ||
                !gr.isValid() ||
                !gr.get(interviewId)) {

                data.submitError =
                    'Interview record was not found.';

                return;

            }



            /* an interviewer can only evaluate his / her own interviews */
            if (!seeAll) {


                var interviewerField =
                    findField(gr, INTERVIEWER_FIELDS);


                if (!interviewerField ||
                    gr.getValue(interviewerField) !== gs.getUserID()) {

                    data.submitError =
                        'You can only evaluate your own interviews.';

                    return;

                }

            }



            var feedbackField =
                findField(gr, FEEDBACK_FIELDS);

            var resultField =
                findField(gr, RESULT_FIELDS);

            var statusField =
                findField(gr, STATUS_FIELDS);


            if (!feedbackField || !resultField) {

                data.submitError =
                    'The interview table needs a feedback field and a result field.';

                return;

            }


            if (classifyResult(
                gr.getDisplayValue(resultField)
            ) !== 'none') {

                data.submitError =
                    'This interview has already been evaluated.';

                return;

            }



            /* ---------- feedback text (ratings + comments) ---------- */


            var overall =
                (
                    (
                        technical +
                        communication +
                        problemSolving +
                        professionalism
                    ) / 4
                ).toFixed(1);


            var feedback =

                'Technical Skills: ' +
                technical +
                '/5\n' +

                'Communication: ' +
                communication +
                '/5\n' +

                'Problem Solving: ' +
                problemSolving +
                '/5\n' +

                'Professionalism: ' +
                professionalism +
                '/5\n' +

                'Overall Rating: ' +
                overall +
                '/5\n' +

                'Recommendation: ' +
                recommendations[recommendation].label +
                '\n' +

                'Evaluated by: ' +
                gs.getUserDisplayName() +
                '\n\n' +

                'Comments:\n' +
                comments;


            gr.setValue(
                feedbackField,
                feedback
            );



            /* ---------- result ---------- */


            var outcome =
                recommendations[recommendation].outcome;

            var pick;


            if (outcome === 'pass') {

                pick = pickChoice(
                    gr,
                    resultField,
                    ['pass', 'select', 'hire', 'clear'],
                    ['not ', 'reject', 'fail']
                );

            } else if (outcome === 'fail') {

                pick = pickChoice(
                    gr,
                    resultField,
                    ['fail', 'reject', 'not select'],
                    []
                );

            } else {

                pick = pickChoice(
                    gr,
                    resultField,
                    ['hold'],
                    []
                );

            }



            if (pick.hasChoices) {


                if (pick.value) {


                    gr.setValue(
                        resultField,
                        pick.value
                    );


                } else if (outcome !== 'hold') {


                    data.submitError =
                        'Could not find a matching choice in the Result field. ' +
                        'Please make sure it has choices like Passed and Failed.';

                    return;

                }

                /* "Hold" without a matching choice: result stays pending */


            } else {


                /* Result is a plain text field */

                gr.setValue(
                    resultField,

                    outcome === 'pass'
                        ? 'Passed'
                        : (
                            outcome === 'fail'
                                ? 'Failed'
                                : 'On Hold'
                        )
                );

            }



            /* ---------- status -> Completed ---------- */


            if (statusField) {


                var statusPick =
                    pickChoice(
                        gr,
                        statusField,
                        ['complete'],
                        ['in complete', 'incomplete']
                    );


                if (statusPick.hasChoices) {

                    if (statusPick.value) {

                        gr.setValue(
                            statusField,
                            statusPick.value
                        );

                    }

                } else {

                    gr.setValue(
                        statusField,
                        'Completed'
                    );

                }

            }



            /* ---------- save ---------- */


            if (!gr.update()) {

                data.submitError =
                    'Unable to save the evaluation.';

                return;

            }


            data.submitSuccess = true;



        } catch (error) {


            gs.error(
                'NEXORA SUBMIT EVALUATION ERROR: ' +
                error
            );

            data.submitSuccess = false;

            data.submitError =
                'Server error while saving the evaluation.';

        }

    }



    /* =========================================================
       CHOICE HELPER
       Finds the real stored value of a choice from its label,
       so it works with any choice values you configured.
       ========================================================= */

    function pickChoice(gr, field, keywords, excludes) {


        var choices = [];


        try {

            var ch =
                new GlideRecord('sys_choice');

            ch.addQuery(
                'name',
                gr.getTableName()
            );

            ch.addQuery(
                'element',
                field
            );

            ch.addQuery(
                'inactive',
                false
            );

            ch.query();


            while (ch.next()) {

                choices.push({

                    value: ch.getValue('value'),
                    label: ch.getValue('label')

                });

            }

        } catch (e1) {}



        if (choices.length === 0) {

            try {

                var values =
                    gr.getElement(field).getChoices();


                if (values) {

                    for (
                        var v = 0;
                        v < values.length;
                        v++
                    ) {

                        choices.push({
                            value: String(values[v]),
                            label: String(values[v])
                        });

                    }

                }

            } catch (e2) {}

        }



        if (choices.length === 0) {

            return {
                hasChoices: false,
                value: ''
            };

        }



        for (
            var k = 0;
            k < keywords.length;
            k++
        ) {


            for (
                var i = 0;
                i < choices.length;
                i++
            ) {


                var text =
                    normalize(choices[i].label) +
                    ' | ' +
                    normalize(choices[i].value);

                var skip = false;


                for (
                    var x = 0;
                    x < excludes.length;
                    x++
                ) {

                    if (
                        text.indexOf(excludes[x]) !== -1
                    ) {

                        skip = true;

                    }

                }


                if (
                    !skip &&
                    text.indexOf(keywords[k]) !== -1
                ) {

                    return {
                        hasChoices: true,
                        value: choices[i].value
                    };

                }

            }

        }



        return {
            hasChoices: true,
            value: ''
        };

    }



    /* =========================================================
       RELATED RECORDS (cached)
       ========================================================= */

    function getApplication(appId) {


        if (
            applicationCache[appId] !== undefined
        ) {

            return applicationCache[appId];

        }


        var result = null;

        var app =
            new GlideRecord(APPLICATION_TABLE);


        if (
            app.isValid() &&
            app.get(appId)
        ) {


            var driveField =
                findField(
                    app,
                    ['drive', 'placement_drive']
                );


            result = {

                student:
                    app.isValidField('student')
                        ? (app.getValue('student') || '')
                        : '',

                drive:
                    driveField
                        ? (app.getValue(driveField) || '')
                        : ''

            };

        }


        applicationCache[appId] = result;

        return result;

    }



    function getStudent(studentId) {


        if (
            studentCache[studentId] !== undefined
        ) {

            return studentCache[studentId];

        }


        var result = null;

        var gr =
            new GlideRecord(STUDENT_TABLE);


        if (
            gr.isValid() &&
            gr.get(studentId)
        ) {


            var nameField =
                findField(
                    gr,
                    [
                        'student_name',
                        'name',
                        'full_name'
                    ]
                );

            var regField =
                findField(
                    gr,
                    [
                        'register_number',
                        'student_id',
                        'registration_number',
                        'roll_number'
                    ]
                );

            var branchField =
                findField(
                    gr,
                    [
                        'branch',
                        'department',
                        'branch_name'
                    ]
                );

            var yearField =
                findField(
                    gr,
                    [
                        'current_year',
                        'year',
                        'academic_year',
                        'year_of_study',
                        'u_current_year'
                    ]
                );

            var cgpaField =
                findField(
                    gr,
                    [
                        'cgpa',
                        'gpa'
                    ]
                );

            var backlogField =
                findField(
                    gr,
                    [
                        'backlogs',
                        'backlog_count',
                        'no_of_backlogs',
                        'number_of_backlogs'
                    ]
                );



            result = {

                name:
                    (
                        nameField
                            ? gr.getDisplayValue(nameField)
                            : ''
                    ) || 'Student',

                registerNumber:
                    regField
                        ? (
                            gr.getDisplayValue(regField) || ''
                        )
                        : '',

                branch:
                    branchField
                        ? (
                            gr.getDisplayValue(branchField) || ''
                        )
                        : '',

                year:
                    yearField
                        ? (
                            gr.getDisplayValue(yearField) || ''
                        )
                        : '',

                cgpa:
                    cgpaField
                        ? (
                            gr.getValue(cgpaField) || ''
                        )
                        : '',

                backlogs:
                    backlogField
                        ? (
                            gr.getValue(backlogField) || '0'
                        )
                        : ''

            };

        }


        studentCache[studentId] = result;

        return result;

    }



    function getDrive(driveId) {


        if (
            driveCache[driveId] !== undefined
        ) {

            return driveCache[driveId];

        }


        var result = null;

        var gr =
            new GlideRecord(DRIVE_TABLE);


        if (
            gr.isValid() &&
            gr.get(driveId)
        ) {


            result = {

                company:
                    gr.isValidField('company')
                        ? (
                            gr.getDisplayValue('company') || ''
                        )
                        : '',

                position:
                    getFirstValidValue(
                        gr,
                        [
                            'position',
                            'job_role',
                            'role',
                            'job_title',
                            'title'
                        ]
                    )

            };

        }


        driveCache[driveId] = result;

        return result;

    }



    /* =========================================================
       HELPERS
       ========================================================= */

    /* none = not evaluated yet, pass / fail / hold = evaluated */

    function classifyResult(value) {


        var v = normalize(value);


        if (
            !v ||
            v === 'pending' ||
            v === 'not evaluated' ||
            v === 'none'
        ) {

            return 'none';

        }


        if (
            v.indexOf('reject') !== -1 ||
            v.indexOf('fail') !== -1 ||
            v.indexOf('not select') !== -1
        ) {

            return 'fail';

        }


        if (
            v.indexOf('pass') !== -1 ||
            v.indexOf('select') !== -1 ||
            v.indexOf('hire') !== -1 ||
            v.indexOf('clear') !== -1
        ) {

            return 'pass';

        }


        return 'hold';

    }



    function toRating(value) {


        var n = parseInt(value, 10);


        if (
            isNaN(n) ||
            n < 1 ||
            n > 5
        ) {

            return 0;

        }


        return n;

    }



    function findField(gr, fields) {


        for (
            var i = 0;
            i < fields.length;
            i++
        ) {

            if (
                gr.isValidField(fields[i])
            ) {

                return fields[i];

            }

        }


        return '';

    }



    function getFirstValidValue(gr, fields) {


        for (
            var i = 0;
            i < fields.length;
            i++
        ) {


            if (
                gr.isValidField(fields[i])
            ) {


                var value =
                    gr.getDisplayValue(fields[i]) || '';


                if (value) {

                    return value;

                }

            }

        }


        return '';

    }



    function normalize(value) {


        return String(value || '')
            .toLowerCase()
            .replace(/[\_-]/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();

    }



    function getInitial(value) {


        if (!value) {

            return '?';

        }


        return String(value)
            .trim()
            .charAt(0)
            .toUpperCase();

    }



})();
